// CppException.java - std::exception (C# Cpp.CppException : Exception, cs/runtime/Std.cs). A C++ throw is a Java
// throw of one of these (or of an engine class derived from one); its library subclasses are generated by
// java/tools/gen_core.py. The message is a Str, as what() returns a const char*.
// Written by Claude (Anthropic) for the SWMM6 ports; see AI-USE.md.
package cpp;

public class CppException extends RuntimeException {
	public final Str msg;
	public CppException() { super("std::exception"); msg = new Str("std::exception"); }
	public CppException(Str m) { super(m.toString()); msg = m.Clone(); }
	public CPtr what() { return msg.c_str(); }
}
